├── test17.mjs          (entry point)
└── lib
    ├── strutils.mjs    (camel2under, under2camel, slugify, pluralize, cardinalize, unitLen)
    ├── dictutils.mjs   (FrozenDict)
    ├── pyrepr.mjs      (Python repr/print rendering)
    └── argparse.mjs    (manual argv parsing)
```

