```js
// Pure-ESM port of boltons.strutils functions.
// No external dependencies; ASCII-only character classes where noted to
// match Python boltons semantics exactly.

const CAMEL2UNDER_RE = /((?<=[a-z0-9])[A-Z]|(?!^)[A-Z](?=[a-z]))/g;

export function camel2under(s) {
  return s.replace(CAMEL2UNDER_RE, '_$&').toLowerCase();
}

function capitalize(w) {
  // Python str.capitalize: first character uppercased, rest lowercased.
  const first = [...w][0];
  return first.toUpperCase() + w.slice(first.length).toLowerCase();
}

export function under2camel(s) {
  // boltons: ''.join(w.capitalize() or '_' for w in s.split('_'))
  // Every segment is capitalized (rest lowercased); empty segments become '_'.
  return s
    .split('_')
    .map((w) => (w ? capitalize(w) : '_'))
    .join('');
}

export function slugify(s) {
  // boltons: split into runs of word characters (letters/digits, underscore
  // excluded — it acts as a delimiter and is re-inserted by the join).
  const words = s.toLowerCase().match(/[\p{L}\p{N}]+/gu);
  return words ? words.join('_') : '';
}

const PLURAL_S_X_Z_CH_SH = /(s|x|z|ch|sh)$/i;
const CONSONANT_Y = /[^aeiou]y$/i;

export function pluralize(word) {
  if (!word) return word;
  if (PLURAL_S_X_Z_CH_SH.test(word)) {
    return word + 'es';
  }
  if (CONSONANT_Y.test(word)) {
    return word.slice(0, -1) + 'ies';
  }
  return word + 's';
}

export function cardinalize(unitNoun, count) {
  return count === 1 ? unitNoun : pluralize(unitNoun);
}

export function unitLen(arr, unitNoun = 'item') {
  const count = arr.length;
  return `${count} ${cardinalize(unitNoun, count)}`;
}
```

