`/output/lib/pyrepr.mjs`:

```js
// Helpers that render values exactly like Python's repr()/print().
// No imports; pure ESM.

export function pyReprStr(s) {
  // Choose quote: single quotes, unless the string contains a single quote
  // and no double quote, in which case use double quotes.
  const quote = s.includes("'") && !s.includes('"') ? '"' : "'";
  let out = quote;
  for (const ch of s) {
    const code = ch.codePointAt(0);
    if (ch === '\\') {
      out += '\\\\';
    } else if (ch === quote) {
      out += '\\' + quote;
    } else if (ch === '\n') {
      out += '\\n';
    } else if (ch === '\r') {
      out += '\\r';
    } else if (ch === '\t') {
      out += '\\t';
    } else if (code < 32 || code === 127) {
      out += '\\x' + code.toString(16).padStart(2, '0');
    } else {
      out += ch;
    }
  }
  out += quote;
  return out;
}

export function pyReprList(arr) {
  return '[' + arr.map(pyRepr).join(', ') + ']';
}

export function pyDictRepr(entries) {
  return '{' + entries.map(([k, v]) => pyRepr(k) + ': ' + pyRepr(v)).join(', ') + '}';
}

export function pyRepr(value) {
  if (typeof value === 'string') return pyReprStr(value);
  if (typeof value === 'number') return String(value);
  if (Array.isArray(value)) return pyReprList(value);
  if (value !== null && typeof value === 'object' && Array.isArray(value.pairs)) {
    return pyDictRepr(value.pairs);
  }
  return String(value);
}
```

`/output/lib/argparse.mjs`:

```js
import { basename } from 'node:path';

function usageLine(prog) {
  return `usage: ${prog} [-h] --a A\n`;
}

function printHelp(prog) {
  process.stdout.write(
    usageLine(prog) +
      '\n' +
      'options:\n' +
      '  -h, --help  show this help message and exit\n' +
      '  --a A       Comma-separated strings\n'
  );
}

function fail(prog, message) {
  process.stderr.write(usageLine(prog) + `${prog}: error: ${message}\n`);
  process.exit(2);
}

export function parseArgs(argv) {
  const prog = basename(argv[1]);
  const args = argv.slice(2);

  let a;
  const unrecognized = [];

  for (let i = 0; i < args.length; i++) {
    const arg = args[i];
    if (arg === '-h' || arg === '--help') {
      printHelp(prog);
      process.exit(0);
    } else if (arg === '--a') {
      const next = args[i + 1];
      if (next === undefined || (next.length > 1 && next.startsWith('-'))) {
        fail(prog, 'argument --a: expected one argument');
      }
      a = next;
      i++;
    } else if (arg.startsWith('--a=')) {
      a = arg.slice('--a='.length);
    } else {
      unrecognized.push(arg);
    }
  }

  if (a === undefined) {
    fail(prog, 'the following arguments are required: --a');
  }
  if (unrecognized.length > 0) {
    fail(prog, `unrecognized arguments: ${unrecognized.join(' ')}`);
  }

  return { a };
}
```

